// <auto-generated> area: command-id bindings for the generated protobuf messages.
// Mirrors the Rust #[cmd(id)] derive; update via the partial classes here.

namespace Lunaria.Proto;

/// <summary>
/// Binds a protobuf message type to the <see cref="Msg.EClientServerCmds"/> value the
/// client expects on the wire. This is the C# analogue of the Rust project's
/// <c>#[cmd(id)]</c> attribute: the message classes themselves are generated by
/// Grpc.Tools as <c>partial</c> classes, and the per-proto files under
/// <c>Generated/Cmds/</c> extend each one that participates in routing with
/// this attribute.
/// </summary>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = false, Inherited = false)]
public sealed class CmdAttribute : Attribute
{
    /// <summary>Command id carried in <c>CSMsgHead.cmd</c>.</summary>
    public uint CmdId { get; }

    public CmdAttribute(uint cmdId) => CmdId = cmdId;
}

/// <summary>
/// Registry that answers "which command id does this message type carry?".
/// Populated once by reflection over every <see cref="CmdAttribute"/> in this
/// assembly; lookup is a dictionary hit afterwards.
/// </summary>
public static class MessageCmdRegistry
{
    private static readonly Dictionary<Type, uint> CmdIdsByType = Build();

    /// <summary>Command id for a message instance, or <see langword="null"/> when the
    /// type carries no binding.</summary>
    public static uint? CmdIdOf(global::Google.Protobuf.IMessage message)
        => CmdIdsByType.TryGetValue(message.GetType(), out var id) ? id : null;

    /// <summary>Command id for a message type, or <see langword="null"/> when the
    /// type carries no binding.</summary>
    public static uint? CmdIdOf<T>() where T : global::Google.Protobuf.IMessage
        => CmdIdsByType.TryGetValue(typeof(T), out var id) ? id : null;

    /// <summary>Command id for an arbitrary message type.</summary>
    public static bool TryGetCmdId(Type messageType, out uint cmdId)
        => CmdIdsByType.TryGetValue(messageType, out cmdId!);

    /// <summary>All bindings, keyed by command id (useful for diagnostics).</summary>
    public static IReadOnlyDictionary<uint, Type> TypesByCmdId { get; } =
        CmdIdsByType.ToDictionary(kv => kv.Value, kv => kv.Key);

    private static Dictionary<Type, uint> Build()
    {
        var map = new Dictionary<Type, uint>();
        foreach (var type in typeof(MessageCmdRegistry).Assembly.GetTypes())
        {
            var attr = type.GetCustomAttributes(typeof(CmdAttribute), inherit: false)
                .Cast<CmdAttribute>()
                .FirstOrDefault();
            if (attr is null)
                continue;

            if (!typeof(global::Google.Protobuf.IMessage).IsAssignableFrom(type))
                throw new InvalidOperationException(
                    $"{type.FullName} carries [Cmd({attr.CmdId})] but is not a protobuf message.");

            if (!map.TryAdd(type, attr.CmdId))
                throw new InvalidOperationException(
                    $"Duplicate [Cmd] registration for {type.FullName}.");
        }

        return map;
    }
}
